<script setup>
import {computed,onMounted,ref} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {api} from '../bridge/jcefBridge';import PageShell from '../components/common/PageShell.vue';
const rows=ref([]),page=ref(1),size=ref(16),dialog=ref(false),form=ref(empty());const paged=computed(()=>rows.value.slice((page.value-1)*size.value,page.value*size.value));function empty(){return{id:null,name:'',preamble:''}}async function load(){rows.value=await api('prompts.list')}function edit(x){form.value={...x};dialog.value=true}function create(){form.value=empty();dialog.value=true}async function save(){await api('prompt.save',form.value);ElMessage.success('提示词已保存');dialog.value=false;load()}async function remove(x){await ElMessageBox.confirm(`确定删除提示词“${x.name}”吗？`,'删除提示词',{type:'warning'});await api('prompt.delete',{id:x.id});ElMessage.success('提示词已删除');load()}onMounted(load)
</script>
<template><PageShell title="提示词管理"><template #actions><el-button type="primary" @click="create">新增提示词</el-button></template><div class="card-page"><div class="prompt-cards"><article v-for="x in paged" :key="x.id" class="content-card"><header><strong>{{x.name}}</strong><small>{{x.updatedAt||'未记录更新时间'}}</small></header><pre>{{x.preamble}}</pre><footer><el-button size="small" @click="edit(x)">编辑</el-button><el-button size="small" type="danger" plain @click="remove(x)">删除</el-button></footer></article></div><div class="card-pagination"><el-pagination v-model:current-page="page" v-model:page-size="size" :page-sizes="[8,16,20,50]" layout="总数,total, sizes, prev, pager, next" :total="rows.length"/></div></div><el-dialog v-model="dialog" title="提示词编辑" width="760px"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="系统提示词"><el-input v-model="form.preamble" type="textarea" resize="none" :rows="18"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存提示词</el-button></template></el-dialog></PageShell></template>
